const { requireWithFallback } = require('./require-package');

const { SYNC_OBJECT_TYPES } = requireWithFallback(
  require,
  '@synclistic/types',
  '../../types'
);
const { SyncCoreError } = require('./errors');

const VALID_SYNC_OBJECT_TYPES = SYNC_OBJECT_TYPES;

const SYNC_DEPENDENCIES = Object.freeze({
  menus: ['pages', 'blogs'],
  articles: ['blogs'],
  products: ['collections', 'themes'],
  pages: ['themes'],
  collections: ['themes'],
  metafields: ['products', 'pages', 'blogs', 'articles', 'collections'],
  metaobjects: ['products', 'pages', 'blogs', 'articles', 'metafields', 'collections']
});

function getSyncOrder(selectedObjects) {
  const order = [];
  const visited = new Set();
  const visiting = new Set();

  function visit(objectType, ancestry) {
    if (visiting.has(objectType)) {
      const cycle = [...ancestry, objectType].join(' -> ');
      throw new SyncCoreError(
        'CIRCULAR_DEPENDENCY',
        `Circular dependency detected: ${cycle}`,
        { objectType, cycle: [...ancestry, objectType] }
      );
    }

    if (visited.has(objectType)) {
      return;
    }

    visiting.add(objectType);

    const dependencies = SYNC_DEPENDENCIES[objectType] || [];
    for (const dependency of dependencies) {
      if (selectedObjects.includes(dependency)) {
        visit(dependency, [...ancestry, objectType]);
      }
    }

    visiting.delete(objectType);
    visited.add(objectType);
    order.push(objectType);
  }

  for (const objectType of selectedObjects) {
    if (!visited.has(objectType)) {
      visit(objectType, []);
    }
  }

  return order;
}

module.exports = {
  VALID_SYNC_OBJECT_TYPES,
  SYNC_DEPENDENCIES,
  getSyncOrder
};
